const MOD = 998244353n;

function bpow(a, b) {
    let res = 1n;
    a %= MOD;
    while (b > 0n) {
        if (b & 1n) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1n;
    }
    return res;
}

const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
const n = parseInt(input[0]);
const a = parseInt(input[1]);
const b = parseInt(input[2]);

const pless = (BigInt(a) * bpow(BigInt(b), MOD - 2n)) % MOD;
const pgreater = (BigInt(b - a) * bpow(BigInt(b), MOD - 2n)) % MOD;

const pow_pless = Array(n + 1).fill(1n);
const pow_pgreater = Array(n + 1).fill(1n);
for (let i = 1; i <= n; ++i) {
    pow_pless[i] = (pow_pless[i - 1] * pless) % MOD;
    pow_pgreater[i] = (pow_pgreater[i - 1] * pgreater) % MOD;
}

const CP = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0n));
for (let i = 0; i <= n; ++i) {
    for (let j = 0; j <= i; ++j) {
        if (j === 0) {
            CP[i][j] = 1n;
        } else {
            const term1 = (CP[i - 1][j - 1] * pow_pgreater[i - j]) % MOD;
            const term2 = (CP[i - 1][j] * pow_pless[j]) % MOD;
            CP[i][j] = (term1 + term2) % MOD;
        }
    }
}

const STRONG = Array(n + 1).fill(0n);
for (let i = 0; i <= n; ++i) {
    STRONG[i] = 1n;
    if (i > 1) {
        for (let j = 1; j < i; ++j) {
            STRONG[i] = (STRONG[i] - (STRONG[j] * CP[i][j]) % MOD + MOD) % MOD;
        }
    }
}

const ans = Array(n + 1).fill(0n);
for (let i = 0; i <= n; ++i) {
    if (i < 2) {
        ans[i] = 0n;
    } else {
        let sum = 0n;
        for (let j = 1; j <= i; ++j) {
            const term_a = BigInt(j) * BigInt(i - j);
            const term_b = (BigInt(j) * BigInt(j - 1)) / 2n;
            const term_c = (j < i ? ans[j] : 0n);
            const term_d = ans[i - j];
            const val = (term_a + term_b + term_c + term_d) % MOD;
            const coeff = (STRONG[j] * CP[i][j]) % MOD;
            sum = (sum + coeff * val) % MOD;
        }
        let coef = (1n - (STRONG[i] * CP[i][i]) % MOD + MOD) % MOD;
        ans[i] = (sum * bpow(coef, MOD - 2n)) % MOD;
    }
}

console.log(ans[n].toString());

