const MOD = 998244353;

function modAdd(a, b) {
    let res = a + b;
    if (res >= MOD) res -= MOD;
    return res;
}

function modSub(a, b) {
    let res = a - b;
    if (res < 0) res += MOD;
    return res;
}

function modMul(a, b) {
    return (a * b) % MOD;
}

function modPow(a, e) {
    let res = 1;
    while (e > 0) {
        if (e & 1) res = modMul(res, a);
        a = modMul(a, a);
        e >>= 1;
    }
    return res;
}

function modInv(a) {
    return modPow(a, MOD - 2);
}

const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
if (input.length < 3) process.exit(0);
const n = parseInt(input[0]);
const a = parseInt(input[1]);
const b = parseInt(input[2]);

const inv_b = modInv(b);
const pless = modMul(a, inv_b);
const pgreater = modMul(modSub(b, a), inv_b);

const pow_pless = new Array(n + 1);
const pow_pgreater = new Array(n + 1);
pow_pless[0] = 1;
pow_pgreater[0] = 1;
for (let i = 1; i <= n; i++) {
    pow_pless[i] = modMul(pow_pless[i - 1], pless);
    pow_pgreater[i] = modMul(pow_pgreater[i - 1], pgreater);
